INSERT INTO RENTAL (
    equipment_id, user_id, quantity, purpose,
    request_status, rental_date, return_date
) VALUES (
    #{equipmentId}, #{userId}, 1, #{purpose},
    'REQUESTED', #{rentalDate}, #{returnDate}
)

mapper.update:
UPDATE EQUIPMENT
SET status = #{status}, updated_at = NOW()
WHERE equipment_id = #{equipmentId}

UPDATE RENTAL
SET request_status = 'REJECTED'
WHERE rental_id = #{rentalId}

UPDATE RENTAL
SET extend_status = 'REQUESTED',
    requested_return_date = #{newReturnDate},
    extend_reason = #{reason}
WHERE rental_id = #{rentalId}
AND user_id = #{userId}

UPDATE RENTAL
SET extend_status = 'REJECTED'
WHERE rental_id = #{rentalId}
